	StatusOpen,
	StatusInProgress,
	StatusFixed,
	StatusWontFix,
	StatusAccepted,
}

// ValidSeverity reports whether severity is one of the published values.
func ValidSeverity(severity Severity) bool {
	for _, candidate := range Severities {
		if severity == candidate {
			return true
		}
	}
	return false
}

// ValidStatus reports whether status is one of the published values.
func ValidStatus(status Status) bool {
	for _, candidate := range Statuses {
		if status == candidate {
			return true
		}
	}
	return false
}

// Range is one affected-version interval. An empty lower or upper bound means
// the interval is open on that side. The include flags state explicitly
// whether a present bound is inclusive.
type Range struct {
	Lower        string `json:"lower"`
	LowerInclude *bool  `json:"lower_include"`
	Upper        string `json:"upper"`
	UpperInclude *bool  `json:"upper_include"`
}

// Vulnerability is the full stored record returned by create, update and
// affected-lookup entries.
type Vulnerability struct {
	ID             string  `json:"id"`
	Component      string  `json:"component"`
	Ranges         []Range `json:"affected_ranges"`
	Severity       Severity
	FixedVersion   string
	Status         Status
	lowerParsed    []Version
	upperParsed    []Version
}

// ValidateRanges parses every bound and rejects malformed versions or
// inverted intervals. On success the parsed bounds are cached on v for
// Contains.
func (v *Vulnerability) ValidateRanges() error {
	count := len(v.Ranges)
	if count == 0 {
		return errInvalidVersion
	}
	lowerParsed := make([]Version, count)
	upperParsed := make([]Version, count)
	for index, affected := range v.Ranges {
		if affected.Lower != "" {
			if affected.LowerInclude == nil {
				return errInvalidVersion
			}
			parsed, err := ParseVersion(affected.Lower)
			if err != nil {
				return err
			}
			lowerParsed[index] = parsed
		}
		if affected.Upper != "" {
			if affected.UpperInclude == nil {
				return errInvalidVersion
			}
			parsed, err := ParseVersion(affected.Upper)
			if err != nil {
				return err
			}
			upperParsed[index] = parsed
		}
		if affected.Lower != "" && affected.Upper != "" {
			switch lowerParsed[index].Compare(upperParsed[index]) {
			case 1:
				return errInvalidVersion
			case 0:
				if !*affected.LowerInclude || !*affected.UpperInclude {
					return errInvalidVersion
				}
			}
		}
	}
	v.lowerParsed = lowerParsed
	v.upperParsed = upperParsed
	return nil
}

// Contains reports whether version lies in the union of affected ranges.
// Ranges must have been validated first.
func (v *Vulnerability) Contains(version Version) bool {
	for index, affected := range v.Ranges {
		if affected.Lower != "" {
			compare := lowerParsedOrZero(v, index).Compare(version)
			if compare > 0 || (compare == 0 && !*affected.LowerInclude) {
				continue
			}
		}
		if affected.Upper != "" {
			compare := version.Compare(upperParsedOrZero(v, index))
			if compare > 0 || (compare == 0 && !*affected.UpperInclude) {
				continue
			}
		}
		return true
	}
	return false
}

// MatchedRanges returns the affected ranges that contain version, preserving
// registration order.
func (v *Vulnerability) MatchedRanges(version Version) []Range {
	matched := []Range{}
	for index, affected := range v.Ranges {
		if affected.Lower != "" {
			compare := lowerParsedOrZero(v, index).Compare(version)
			if compare > 0 || (compare == 0 && !*affected.LowerInclude) {
				continue
			}
		}
		if affected.Upper != "" {
			compare := version.Compare(upperParsedOrZero(v, index))
			if compare > 0 || (compare == 0 && !*affected.UpperInclude) {
				continue
			}
		}
		matched = append(matched, affected)
	}
	return matched
}

func lowerParsedOrZero(v *Vulnerability, index int) Version { return v.lowerParsed[index] }
func upperParsedOrZero(v *Vulnerability, index int) Version { return v.upperParsed[index] }
