func sampleVulnerability(id string) *vuln.Vulnerability {
	lowerTrue := true
	upperFalse := false
	return &vuln.Vulnerability{
		ID:           id,
		Component:    "libxml2",
		Severity:     vuln.SeverityHigh,
		FixedVersion: "2.10.0",
		Status:       vuln.StatusOpen,
		Ranges: []vuln.Range{
			{Lower: &[]string{"2.0"}[0], LowerInclude: &lowerTrue},
