	if loaded.Ranges[0].UpperText() != "" || loaded.Ranges[1].UpperText() != "2.9.9" {
		t.Fatalf("range bounds wrong: %#v", loaded.Ranges)
	}
	if *loaded.Ranges[1].UpperInclude {
		t.Fatalf("second upper bound should be exclusive")
